const TAXES=['IMPOSTOS','IR'];

const onlyDigits=v=>String(v||'').replace(/\D/g,'');
const dateISOFromBR=v=>{const m=String(v||'').match(/\b(0[1-9]|[12]\d|3[01])[\/.-](0[1-9]|1[0-2])[\/.-](20\d{2})\b/);return m?`${m[3]}-${m[2]}-${m[1]}`:''};
const amountFromBarcode=digits=>{const d=onlyDigits(digits);if(d.length===44){const cents=Number(d.slice(-10));return cents>0?cents/100:0}if(d.length===47){const cents=Number(d.slice(37,47));return cents>0?cents/100:0}if(d.length===48){const cents=Number(d.slice(-10));return cents>0?cents/100:0}return 0};
const bestBarcodeFromText=text=>{const candidates=String(text||'').split(/\n/).map(x=>onlyDigits(x)).filter(x=>[44,47,48].includes(x.length));if(candidates.length)return candidates[0];const all=onlyDigits(text);for(const size of [48,47,44]){for(let i=0;i<=all.length-size;i++){const c=all.slice(i,i+size);if(c.length===size)return c}}return''};
async function readBoletoImage(file,onProgress=()=>{}){
  const url=URL.createObjectURL(file);let barcode='';let text='';
  try{
    if('BarcodeDetector' in window){
      const detector=new window.BarcodeDetector({formats:['itf','code_128','ean_13','ean_8','codabar']});
      const bitmap=await createImageBitmap(file);const found=await detector.detect(bitmap);bitmap.close?.();
      barcode=onlyDigits(found?.[0]?.rawValue||'');
    }
  }catch(e){console.warn('BarcodeDetector:',e)}
  if(![44,47,48].includes(barcode.length)){
    const {recognize}=await import('tesseract.js');
    const result=await recognize(file,'por+eng',{logger:m=>{if(m.status==='recognizing text')onProgress(Math.round((m.progress||0)*100))}});
    text=result?.data?.text||'';barcode=bestBarcodeFromText(text);
  }
  const value=amountFromBarcode(barcode);const due=dateISOFromBR(text);
  return{barcode,text,value,due,url};
}
const NAV_GROUPS=[
 {label:'Visão geral',items:[['Orçamento',LayoutDashboard],['DRE',FileText],['Fluxo de Caixa',TrendingUp],['Planejamento e Projeções',CalendarDays]]},
 {label:'Movimentações',items:[['DADOS',Database],['Boletos',ReceiptText],['Recebimento',ArrowDownCircle],['Ciclo Financeiro',RefreshCw]]},
 {label:'Análises',items:[['Vr. Mensal',CalendarDays],['Análise Custo/Despesa',BarChart3],['Análise de Custos',PieChart],['Análise de Despesas',ReceiptText],['Margem de Lucro',DollarSign]]},
 {label:'Cadastros e saída',items:[['Naturezas',ListTree],['Exportar Excel',Download]]}
];
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const num=v=>Number(v||0);
const uid=()=>`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const norm=v=>String(v||'').trim().replace(/\s+/g,' ').toUpperCase();
const statusNorm=v=>String(v||'pendente').toLowerCase();
const isSettled=l=>['pago','recebido'].includes(statusNorm(l.status));
const typeNorm=v=>String(v||'').toLowerCase().includes('entra')||String(v||'').toLowerCase().includes('rece')?'entrada':'saida';
const displayType=v=>typeNorm(v)==='entrada'?'Entrada':'Saída';
const refMonth=l=>Number.isFinite(+l.mes_referencia)?+l.mes_referencia-1:Math.max(0,Math.min(11,+(String(l.data||'').slice(5,7)||1)-1));
const refYear=l=>Number.isFinite(+l.ano_referencia)?+l.ano_referencia:+String(l.data||'').slice(0,4)||2026;
const dateBR=s=>s?String(s).split('-').reverse().join('/'):'—';
const pct=(a,b)=>b?`${(a/b*100).toFixed(1)}%`:'0,0%';

function inferFornecedor(l){
 const d=norm(l.descricao);
 if(d.includes('CHAPAS PRENSA'))return 'CORTAÇO';
 if(d.includes('MATERIAIS ELÉTRICOS')||d.includes('MATERIAIS ELETRICOS'))return 'EQUIFLEX';
 if(d.includes('VÁLVULAS PIRACICABA')||d.includes('VALVULAS PIRACICABA'))return 'PIRACICABA';
 if((d==='VÁLVULAS'||d==='VALVULAS')&&num(l.valor)===900)return 'CONTROL STAR';
 if(d.includes('VÁLVULAS')||d.includes('VALVULAS'))return 'PIRACICABA';
 if(d.includes('MOTOVIBRADOR')||d.includes('MOTORES'))return 'MVL MÁQUINAS';
 if(d.includes('UNIDADES HIDRÁULICAS LYCOS')||d.includes('UNIDADES HIDRAULICAS LYCOS'))return 'LYCOS';
 return l.descricao||l.natureza_nome||'FORNECEDOR';
}
function deriveBoletos(transactions){
 return transactions.filter(l=>typeNorm(l.tipo)==='saida'&&statusNorm(l.status)==='pendente').map((l,i)=>({
  id:`auto-boleto-${l.id??i}`, fornecedor:inferFornecedor(l), natureza_id:l.natureza_id||'', natureza_nome:l.natureza_nome||'',
  lancamento_id:l.id, descricao:l.descricao||'', competencia_mes:7, competencia_ano:2026,
  data_vencimento:l.data_vencimento||l.data||'', valor:num(l.valor), status:'pendente', codigo_barras:'', arquivo_url:'', automatico:true
 }));
}
function migrate(raw){
 const transactions=(raw.transactions||raw.lancamentos||[]).map((x,i)=>{
   const date=x.data||x.date||'2026-01-01';
   return {
    id:x.id??uid()+i, descricao:x.descricao??x.description??'', natureza_id:x.natureza_id??'',
    natureza_nome:x.natureza_nome??x.nature??'OUTROS', tipo:typeNorm(x.tipo??x.type), valor:num(x.valor??x.value),
    data:date, data_vencimento:x.data_vencimento??x.dueDate??'', status:statusNorm(x.status), observacao:x.observacao??x.note??'',
    mes_referencia:num(x.mes_referencia)||num(String(date).slice(5,7))||1,
    ano_referencia:num(x.ano_referencia)||num(String(date).slice(0,4))||2026
   };
 });
 const natures=(raw.natures||raw.naturezas||[]).map((x,i)=>({id:x.id??uid()+i,nome:x.nome??x.name??'',tipo:x.tipo??x.type??'despesa',ativo:x.ativo??x.active??true}));
 const explicitBoletos=raw.boletos||[];
 const boletos=explicitBoletos.length?explicitBoletos:deriveBoletos(transactions);
 return {transactions,natures,budgets:raw.budgets||raw.orcamentos||[],boletos,projections:raw.projections||[],projectionSettings:{lookback:3,safety:10,openingBalance:0,...raw.projectionSettings}};
}

function Modal({title,onClose,children,size=''}){return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className={`modal ${size}`}><div className="modalHead"><h3>{title}</h3><button className="iconBtn" onClick={onClose}><X/></button></div>{children}</div></div>}
function Field({label,...p}){return <label className="field"><span>{label}</span><input {...p}/></label>}
function SelectField({label,children,...p}){return <label className="field"><span>{label}</span><select {...p}>{children}</select></label>}
function TextArea({label,...p}){return <label className="field span2"><span>{label}</span><textarea {...p}/></label>}
function KPI({title,value,tone='green',icon:Icon=WalletCards,sub}){return <div className={`kpi ${tone}`}><div><small>{title}</small><strong>{value}</strong>{sub&&<em>{sub}</em>}</div><Icon size={34}/></div>}
function Header({title,subtitle,month,setMonth,year,setYear,yearOnly=false,action}){return <div className="pageHeader"><div><h1>{title}</h1><p>{subtitle}</p></div><div className="headerActions">{!yearOnly&&<select value={month} onChange={e=>setMonth(+e.target.value)}>{MONTHS.map((m,i)=><option key={m} value={i}>{m}</option>)}</select>}<select value={year} onChange={e=>setYear(+e.target.value)}>{[2024,2025,2026,2027,2028,2029,2030].map(y=><option key={y} value={y}>{y}</option>)}</select>{action}</div></div>}
function Card({title,children,className=''}){return <section className={`card ${className}`}><h3>{title}</h3>{children}</section>}
function Empty({text='Nenhum registro encontrado.'}){return <div className="empty"><Database/><p>{text}</p></div>}
function Badge({children,tone='gray'}){return <span className={`badge ${tone}`}>{children}</span>}
function StatusBadge({status}){const s=statusNorm(status);return <Badge tone={s==='pago'||s==='recebido'?'ok':s==='cancelado'?'gray':'warn'}>{s}</Badge>}
function ConfirmDelete({title,onConfirm,onClose}){return <Modal title={title} onClose={onClose}><div className="confirmBox"><AlertTriangle/><p>Esta ação não poderá ser desfeita.</p><div className="modalActions"><button className="secondary" onClick={onClose}>Cancelar</button><button className="dangerBtn" onClick={onConfirm}><Trash2/>Excluir</button></div></div></Modal>}

function LoginScreen({onSession}){
 const[email,setEmail]=useState(''); const[password,setPassword]=useState(''); const[busy,setBusy]=useState(false); const[error,setError]=useState('');
 const submit=async e=>{e.preventDefault();setBusy(true);setError('');const{data,error}=await supabase.auth.signInWithPassword({email,password});setBusy(false);if(error){setError('E-mail ou senha inválidos. Confira o usuário criado no Supabase.');return}onSession(data.session)};
 if(!supabaseConfigured)return <div className="authShell"><div className="authCard setupCard"><img src="/assets/logo-gift.jpg" alt="GIFT Excellence"/><CloudOff/><h1>Supabase ainda não configurado</h1><p>Adicione as variáveis <b>VITE_SUPABASE_URL</b> e <b>VITE_SUPABASE_PUBLISHABLE_KEY</b> na Vercel ou no arquivo <code>.env.local</code>.</p><div className="setupSteps"><span>1</span><p>Execute o arquivo <b>supabase/schema.sql</b> no SQL Editor.</p><span>2</span><p>Crie o primeiro usuário em Authentication → Users.</p><span>3</span><p>Configure as variáveis e publique novamente.</p></div></div></div>;
 return <div className="authShell"><form className="authCard" onSubmit={submit}><img src="/assets/logo-gift.jpg" alt="GIFT Excellence"/><div className="authIcon"><ShieldCheck/></div><h1>Financeiro GIFT</h1><p>Acesso seguro ao banco exclusivo da empresa.</p><label><span>E-mail</span><div><Mail/><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="seu@email.com"/></div></label><label><span>Senha</span><div><LockKeyhole/><input type="password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••"/></div></label>{error&&<div className="authError">{error}</div>}<button disabled={busy}>{busy?<><LoaderCircle className="spin"/>Entrando...</>:<>Entrar no sistema</>}</button><small>Os dados ficam centralizados no Supabase e são compartilhados entre dispositivos autorizados.</small></form></div>
}

function App(){
 const[db,setDb]=useState(migrate({})); const[ready,setReady]=useState(false); const[tab,setTab]=useState('Orçamento');
 const[month,setMonth]=useState(6); const[year,setYear]=useState(2026); const[mobile,setMobile]=useState(false); const[search,setSearch]=useState('');
 const[session,setSession]=useState(null); const[authReady,setAuthReady]=useState(false); const[syncState,setSyncState]=useState('idle'); const[loadError,setLoadError]=useState('');
 const[txModal,setTxModal]=useState(null); const[natModal,setNatModal]=useState(null); const[budgetEdit,setBudgetEdit]=useState(null); const[boletoModal,setBoletoModal]=useState(null); const[projectionModal,setProjectionModal]=useState(null); const[deleteState,setDeleteState]=useState(null);
 const hydrated=useRef(false); const saveTimer=useRef(null);
 useEffect(()=>{if(!supabaseConfigured){setAuthReady(true);return}supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true)});const{data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>{setSession(next);setAuthReady(true)});return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(!authReady||!session)return;(async()=>{setReady(false);setLoadError('');try{let remote=await loadAppState();if(!remote){const initial=await fetch('/data/initialData.json').then(r=>r.json());remote=migrate(initial);await seedAppState(remote)}setDb(migrate(remote));hydrated.current=true;setReady(true)}catch(e){console.error(e);setLoadError(e.message||'Não foi possível carregar o banco.');setReady(true)}})()},[authReady,session?.user?.id]);
 useEffect(()=>{if(!ready||!session||!hydrated.current)return;clearTimeout(saveTimer.current);setSyncState('saving');saveTimer.current=setTimeout(async()=>{try{await saveAppState(db);setSyncState('saved')}catch(e){console.error(e);setSyncState('error')}},650);return()=>clearTimeout(saveTimer.current)},[db,ready,session]);
 const period=useMemo(()=>db.transactions.filter(l=>refMonth(l)===month&&refYear(l)===year),[db.transactions,month,year]);
 const annual=useMemo(()=>db.transactions.filter(l=>refYear(l)===year),[db.transactions,year]);
 const realizedPeriod=useMemo(()=>period.filter(isSettled),[period]); const realizedAnnual=useMemo(()=>annual.filter(isSettled),[annual]);
 const income=realizedPeriod.filter(l=>typeNorm(l.tipo)==='entrada').reduce((s,l)=>s+num(l.valor),0);
 const expense=realizedPeriod.filter(l=>typeNorm(l.tipo)==='saida').reduce((s,l)=>s+num(l.valor),0);
 const groupNature=(rows,type)=>Object.entries(rows.filter(l=>typeNorm(l.tipo)===type).reduce((a,l)=>{const k=l.natureza_nome||'Outros';a[k]=(a[k]||0)+num(l.valor);return a},{})).map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value);
 const saveTx=f=>{const n=db.natures.find(x=>String(x.id)===String(f.natureza_id));const date=f.data||'2026-01-01';const rec={...f,natureza_nome:n?.nome||f.natureza_nome||'OUTROS',valor:num(f.valor),mes_referencia:num(String(date).slice(5,7)),ano_referencia:num(String(date).slice(0,4)),tipo:typeNorm(f.tipo)};setDb(d=>({...d,transactions:f.id?d.transactions.map(x=>String(x.id)===String(f.id)?rec:x):[{...rec,id:uid()},...d.transactions]}));setTxModal(null)};
 const saveNature=f=>{const rec={...f,nome:norm(f.nome),ativo:f.ativo!==false};setDb(d=>({...d,natures:f.id?d.natures.map(x=>String(x.id)===String(f.id)?rec:x):[...d.natures,{...rec,id:uid()}]}));setNatModal(null)};
 const deleteEntity=()=>{if(!deleteState)return;const{kind,id}=deleteState;setDb(d=>kind==='tx'?({...d,transactions:d.transactions.filter(x=>String(x.id)!==String(id))}):kind==='nature'?({...d,natures:d.natures.filter(x=>String(x.id)!==String(id))}):kind==='boleto'?(()=>{const b=d.boletos.find(x=>String(x.id)===String(id));return{...d,boletos:d.boletos.filter(x=>String(x.id)!==String(id)),transactions:b?.lancamento_id?d.transactions.filter(x=>String(x.id)!==String(b.lancamento_id)):d.transactions}})():({...d,projections:d.projections.filter(x=>String(x.id)!==String(id))}));setDeleteState(null)};
 const saveBudget=(natureId,value)=>setDb(d=>{const exists=d.budgets.find(b=>String(b.natureza_id||b.natureId)===String(natureId)&&num(b.mes)===month+1&&num(b.ano)===year);const n=d.natures.find(x=>String(x.id)===String(natureId));const rec={id:exists?.id||uid(),natureza_id:natureId,natureza_nome:n?.nome||'',mes:month+1,ano:year,valor_previsto:num(value),valor_realizado:0};return{...d,budgets:exists?d.budgets.map(b=>String(b.id)===String(exists.id)?rec:b):[...d.budgets,rec]}});
 const saveBoleto=f=>{setDb(d=>{const n=d.natures.find(x=>String(x.id)===String(f.natureza_id));let txId=f.lancamento_id||uid();const tx={id:txId,descricao:f.descricao||f.fornecedor,natureza_id:f.natureza_id,natureza_nome:n?.nome||'',tipo:'saida',valor:num(f.valor),data:f.data_vencimento,data_vencimento:f.data_vencimento,status:f.status==='pago'?'pago':'pendente',observacao:'Boleto vinculado',mes_referencia:num(String(f.data_vencimento).slice(5,7)),ano_referencia:num(String(f.data_vencimento).slice(0,4))};const b={...f,id:f.id||uid(),lancamento_id:txId,natureza_nome:n?.nome||'',valor:num(f.valor),competencia_mes:num(f.competencia_mes),competencia_ano:num(f.competencia_ano)};return{...d,boletos:f.id?d.boletos.map(x=>String(x.id)===String(f.id)?b:x):[b,...d.boletos],transactions:d.transactions.some(x=>String(x.id)===String(txId))?d.transactions.map(x=>String(x.id)===String(txId)?tx:x):[tx,...d.transactions]}});setBoletoModal(null)};
 const saveProjection=f=>{const rec={...f,id:f.id||uid(),valor:num(f.valor),mes:num(f.mes),ano:num(f.ano),source:f.source||'Manual'};setDb(d=>({...d,projections:f.id?d.projections.map(x=>String(x.id)===String(f.id)?rec:x):[...d.projections,rec]}));setProjectionModal(null)};
 const resetData=async()=>{if(confirm('Restaurar os dados originais da planilha? Esta ação substituirá o banco compartilhado.')){const initial=await fetch('/data/initialData.json').then(r=>r.json());setDb(migrate(initial))}};
 const logout=()=>supabase?.auth.signOut();
 if(!authReady)return <div className="loading"><LoaderCircle className="spin"/>Verificando acesso...</div>;
 if(!session)return <LoginScreen onSession={setSession}/>;
 if(!ready)return <div className="loading"><LoaderCircle className="spin"/>Carregando banco financeiro...</div>;
 return <div className="app"><header className="realTopbar"><div className="logoBox"><img src="/assets/logo-gift.jpg" alt="GIFT Excellence"/></div><div className="navScroller"><nav className="realNav">{NAV_GROUPS.flatMap(g=>g.items).map(([name,Icon])=><button key={name} className={tab===name?'active':''} onClick={()=>setTab(name)}><Icon/>{name}</button>)}</nav></div><div className={`syncBadge ${syncState}`} title={syncState==='error'?'Erro ao sincronizar':syncState==='saving'?'Salvando no Supabase':'Banco sincronizado'}>{syncState==='error'?<CloudOff/>:<Cloud/>}<span>{syncState==='saving'?'Salvando':syncState==='error'?'Sem sincronizar':'Online'}</span></div><button className="resetTop" title="Restaurar base original" onClick={resetData}><RotateCcw/></button><button className="logoutTop" title="Sair" onClick={logout}><LogOut/></button></header>{loadError&&<div className="globalError">{loadError}</div>}<main className="realMain"><div className="content"><Page tab={tab} db={db} setDb={setDb} month={month} setMonth={setMonth} year={year} setYear={setYear} period={period} annual={annual} realizedPeriod={realizedPeriod} realizedAnnual={realizedAnnual} income={income} expense={expense} groupNature={groupNature} search={search} setSearch={setSearch} setTxModal={setTxModal} setNatModal={setNatModal} setBudgetEdit={setBudgetEdit} setBoletoModal={setBoletoModal} setProjectionModal={setProjectionModal} setDeleteState={setDeleteState} saveBudget={saveBudget}/></div></main>
 {txModal&&<TxModal initial={txModal} natures={db.natures} onSave={saveTx} onClose={()=>setTxModal(null)}/>} {natModal&&<NatureModal initial={natModal} onSave={saveNature} onClose={()=>setNatModal(null)}/>} {budgetEdit&&<BudgetModal initial={budgetEdit} onSave={v=>{saveBudget(budgetEdit.natureId,v);setBudgetEdit(null)}} onClose={()=>setBudgetEdit(null)}/>} {boletoModal&&<BoletoModal initial={boletoModal} natures={db.natures} onSave={saveBoleto} onClose={()=>setBoletoModal(null)}/>} {projectionModal&&<ProjectionModal initial={projectionModal} natures={db.natures} year={year} onSave={saveProjection} onClose={()=>setProjectionModal(null)}/>} {deleteState&&<ConfirmDelete title="Confirmar exclusão" onConfirm={deleteEntity} onClose={()=>setDeleteState(null)}/>} </div>
}

function Page(p){
 const{tab}=p;
 if(tab==='DADOS')return <DadosPage {...p}/>; if(tab==='Naturezas')return <NaturezasPage {...p}/>; if(tab==='Boletos')return <BoletosPage {...p}/>; if(tab==='Orçamento')return <OrcamentoPage {...p}/>; if(tab==='DRE')return <DREPage {...p}/>; if(tab==='Fluxo de Caixa')return <FluxoPage {...p}/>; if(tab==='Vr. Mensal')return <VrMensalPage {...p}/>; if(tab==='Ciclo Financeiro')return <CicloPage {...p}/>; if(tab==='Recebimento')return <RecebimentoPage {...p}/>; if(tab==='Análise Custo/Despesa')return <CustoDespesaPage {...p}/>; if(tab==='Análise de Custos')return <CustosPage {...p}/>; if(tab==='Análise de Despesas')return <DespesasPage {...p}/>; if(tab==='Margem de Lucro')return <MargemPage {...p}/>; if(tab==='Planejamento e Projeções')return <ProjecoesPage {...p}/>; return <ExportPage {...p}/>;
}

function DadosPage({db,search,setSearch,setTxModal,setDeleteState}){const[typeF,setTypeF]=useState('todos');const[statusF,setStatusF]=useState('todos');const rows=db.transactions.filter(l=>(!search||`${l.descricao} ${l.natureza_nome}`.toLowerCase().includes(search.toLowerCase()))&&(typeF==='todos'||typeNorm(l.tipo)===typeF)&&(statusF==='todos'||statusNorm(l.status)===statusF));const importExcel=e=>{const f=e.target.files?.[0];if(!f)return;const rd=new FileReader();rd.onload=ev=>{const wb=XLSX.read(ev.target.result,{type:'array'});const data=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''});alert(`${data.length} linhas lidas. Use a planilha padrão do sistema para garantir todos os campos.`)};rd.readAsArrayBuffer(f)};return <><Header title="DADOS" subtitle="Cadastro central de lançamentos financeiros" month={0} setMonth={()=>{}} year={2026} setYear={()=>{}} yearOnly action={<><label className="secondary fileBtn"><Upload/>Importar Excel<input type="file" accept=".xlsx,.xls" onChange={importExcel}/></label><button className="primary" onClick={()=>setTxModal({descricao:'',natureza_id:db.natures[0]?.id||'',tipo:'saida',valor:'',data:new Date().toISOString().slice(0,10),data_vencimento:'',status:'pendente',observacao:''})}><Plus/>Novo Lançamento</button></>}/><div className="filters"><div className="search"><Search/><input placeholder="Buscar por descrição ou natureza..." value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={typeF} onChange={e=>setTypeF(e.target.value)}><option value="todos">Todos os tipos</option><option value="entrada">Entrada</option><option value="saida">Saída</option></select><select value={statusF} onChange={e=>setStatusF(e.target.value)}><option value="todos">Todos os status</option><option value="pendente">Pendente</option><option value="pago">Pago</option><option value="recebido">Recebido</option><option value="cancelado">Cancelado</option></select><Badge>{rows.length} registros</Badge></div><div className="tableWrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Natureza</th><th>Tipo</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>{rows.slice(0,500).map(r=><tr key={r.id}><td>{dateBR(r.data)}</td><td><b>{r.descricao}</b></td><td>{r.natureza_nome}</td><td><Badge tone={typeNorm(r.tipo)==='entrada'?'ok':'bad'}>{displayType(r.tipo)}</Badge></td><td className={typeNorm(r.tipo)==='entrada'?'positive':'negative'}>{money(r.valor)}</td><td><StatusBadge status={r.status}/></td><td className="actions"><button onClick={()=>setTxModal(r)}><Pencil/></button><button className="danger" onClick={()=>setDeleteState({kind:'tx',id:r.id})}><Trash2/></button></td></tr>)}</tbody></table>{!rows.length&&<Empty/>}{rows.length>500&&<div className="tableNote">Exibindo os primeiros 500 de {rows.length} registros.</div>}</div></>}
function NaturezasPage({db,search,setSearch,setNatModal,setDeleteState}){const rows=db.natures.filter(n=>!search||n.nome.toLowerCase().includes(search.toLowerCase()));return <><Header title="Naturezas" subtitle="Categorias usadas em lançamentos, boletos e orçamentos" month={0} setMonth={()=>{}} year={2026} setYear={()=>{}} yearOnly action={<button className="primary" onClick={()=>setNatModal({nome:'',tipo:'despesa',ativo:true})}><Plus/>Nova Natureza</button>}/><div className="filters"><div className="search"><Search/><input placeholder="Buscar natureza..." value={search} onChange={e=>setSearch(e.target.value)}/></div><Badge>{rows.length} naturezas</Badge></div><div className="tableWrap"><table><thead><tr><th>Nome</th><th>Tipo</th><th>Status</th><th>Ações</th></tr></thead><tbody>{rows.map(n=><tr key={n.id}><td><b>{n.nome}</b></td><td><Badge tone={n.tipo==='receita'?'ok':n.tipo==='transferencia'?'blue':'bad'}>{n.tipo}</Badge></td><td><Badge tone={n.ativo?'ok':'gray'}>{n.ativo?'Ativa':'Inativa'}</Badge></td><td className="actions"><button onClick={()=>setNatModal(n)}><Pencil/></button><button className="danger" onClick={()=>setDeleteState({kind:'nature',id:n.id})}><Trash2/></button></td></tr>)}</tbody></table></div></>}
function OrcamentoPage({db,month,setMonth,year,setYear,realizedPeriod,setBudgetEdit}){const rows=db.natures.map(n=>{const b=db.budgets.find(x=>String(x.natureza_id||x.natureId)===String(n.id)&&num(x.mes)===month+1&&num(x.ano)===year);const previsto=num(b?.valor_previsto??b?.value);const realizado=realizedPeriod.filter(l=>String(l.natureza_id)===String(n.id)||norm(l.natureza_nome)===norm(n.nome)).reduce((s,l)=>s+num(l.valor),0);return{...n,previsto,realizado}});const tp=rows.reduce((s,r)=>s+r.previsto,0),tr=rows.reduce((s,r)=>s+r.realizado,0);return <><Header title="Orçamento" subtitle="Valores previstos versus realizados por natureza" month={month} setMonth={setMonth} year={year} setYear={setYear}/><div className="kpis"><KPI title="Total Previsto" value={money(tp)} icon={WalletCards}/><KPI title="Total Realizado" value={money(tr)} tone="blue" icon={CheckCircle2}/><KPI title="Diferença" value={money(tp-tr)} tone={tp-tr>=0?'green':'red'} icon={TrendingUp}/></div><div className="tableWrap"><table><thead><tr><th>Natureza</th><th>Tipo</th><th>Previsto</th><th>Realizado</th><th>Progresso</th><th>Ação</th></tr></thead><tbody>{rows.map(r=>{const progress=r.previsto?Math.min(r.realizado/r.previsto*100,100):0;return <tr key={r.id}><td><b>{r.nome}</b></td><td><Badge tone={r.tipo==='receita'?'ok':r.tipo==='transferencia'?'blue':'bad'}>{r.tipo}</Badge></td><td>{money(r.previsto)}</td><td>{money(r.realizado)}</td><td><div className="progress"><span style={{width:`${progress}%`}}/><em>{progress.toFixed(0)}%</em></div></td><td className="actions"><button onClick={()=>setBudgetEdit({natureId:r.id,value:r.previsto})}><Pencil/></button></td></tr>})}</tbody></table></div></>}
function DREPage({month,setMonth,year,setYear,income,expense,realizedPeriod,groupNature}){const ri=groupNature(realizedPeriod,'entrada'),re=groupNature(realizedPeriod,'saida');return <><Header title="DRE" subtitle="Demonstração do Resultado do Exercício" month={month} setMonth={setMonth} year={year} setYear={setYear}/><div className="kpis"><KPI title="Receita Bruta" value={money(income)}/><KPI title="Total Despesas" value={money(expense)} tone="red"/><KPI title="Lucro Líquido" value={money(income-expense)} tone={income-expense>=0?'blue':'orange'} icon={DollarSign}/></div><div className="twoCols"><NatureTable title="Receitas por Natureza" rows={ri} total={income}/><NatureTable title="Despesas por Natureza" rows={re} total={expense}/></div><Card title="Resumo DRE"><div className="dre"><div><span>(+) Receita Bruta</span><b>{money(income)}</b></div><div><span>(−) Despesas Totais</span><b className="negative">{money(expense)}</b></div><div className="result"><span>(=) Lucro/Prejuízo Líquido</span><b>{money(income-expense)}</b></div></div></Card></>}
function annualMonthly(rows){let acc=0;return MONTHS.map((_,i)=>{const m=rows.filter(l=>refMonth(l)===i&&isSettled(l));const entradas=m.filter(l=>typeNorm(l.tipo)==='entrada').reduce((s,l)=>s+num(l.valor),0);const saidas=m.filter(l=>typeNorm(l.tipo)==='saida').reduce((s,l)=>s+num(l.valor),0);const saldo=entradas-saidas;acc+=saldo;return{mes:SHORT_MONTHS[i],month:i,Entradas:entradas,Saídas:saidas,saldo,acumulado:acc,Receitas:entradas,Despesas:saidas,lucro:saldo,margem:entradas?saldo/entradas*100:0}})}
function FluxoPage({year,setYear,annual}){const data=annualMonthly(annual),te=data.reduce((s,x)=>s+x.Entradas,0),ts=data.reduce((s,x)=>s+x.Saídas,0);return <><Header title="Fluxo de Caixa" subtitle="Evolução mensal de entradas, saídas e saldo acumulado" month={0} setMonth={()=>{}} year={year} setYear={setYear} yearOnly/><div className="kpis"><KPI title="Total Entradas" value={money(te)}/><KPI title="Total Saídas" value={money(ts)} tone="red"/><KPI title="Saldo Final" value={money(te-ts)} tone={te-ts>=0?'blue':'orange'}/></div><Card title={`Fluxo de Caixa — ${year}`}><ResponsiveContainer width="100%" height={360}><AreaChart data={data}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="mes"/><YAxis tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><Tooltip formatter={money}/><Legend/><Area type="monotone" dataKey="Entradas" fillOpacity={.2} stroke="#15a777" fill="#15a777"/><Area type="monotone" dataKey="Saídas" fillOpacity={.15} stroke="#ef4444" fill="#ef4444"/></AreaChart></ResponsiveContainer></Card><MonthlyTable data={data}/></>}
function VrMensalPage({db,year,setYear,realizedAnnual}){const data=db.natures.map(n=>{const vals=MONTHS.map((_,i)=>realizedAnnual.filter(l=>refMonth(l)===i&&(String(l.natureza_id)===String(n.id)||norm(l.natureza_nome)===norm(n.nome))).reduce((s,l)=>s+num(l.valor),0));return{name:n.nome,type:n.tipo,vals,total:vals.reduce((a,b)=>a+b,0)}}).filter(x=>x.total>0).sort((a,b)=>b.total-a.total);const chart=MONTHS.map((m,i)=>{const r={mes:SHORT_MONTHS[i]};data.slice(0,5).forEach(n=>r[n.name]=n.vals[i]);return r});return <><Header title="Vr. Mensal" subtitle="Evolução mensal de valores por natureza" month={0} setMonth={()=>{}} year={year} setYear={setYear} yearOnly/><Card title={`Top 5 naturezas — ${year}`}><ResponsiveContainer width="100%" height={360}><BarChart data={chart}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="mes"/><YAxis tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><Tooltip formatter={money}/><Legend/>{data.slice(0,5).map((n,i)=><Bar key={n.name} dataKey={n.name} fill={COLORS[i]}/>)}</BarChart></ResponsiveContainer></Card><div className="tableWrap wide"><table><thead><tr><th>Natureza</th><th>Tipo</th>{SHORT_MONTHS.map(m=><th key={m}>{m}</th>)}<th>Total</th></tr></thead><tbody>{data.map(n=><tr key={n.name}><td><b>{n.name}</b></td><td><Badge tone={n.type==='receita'?'ok':'bad'}>{n.type}</Badge></td>{n.vals.map((v,i)=><td key={i}>{money(v)}</td>)}<td><b>{money(n.total)}</b></td></tr>)}</tbody></table></div></>}
function CicloPage({month,setMonth,year,setYear,period}){const statuses=['pendente','pago','recebido','cancelado'];const stats=statuses.map(s=>({name:s,value:period.filter(l=>statusNorm(l.status)===s).reduce((a,l)=>a+num(l.valor),0),count:period.filter(l=>statusNorm(l.status)===s).length}));const realized=stats.filter(x=>['pago','recebido'].includes(x.name)).reduce((s,x)=>s+x.value,0);const done=period.filter(l=>['pago','recebido'].includes(statusNorm(l.status))).length;const rate=period.length?done/period.length*100:0;return <><Header title="Ciclo Financeiro" subtitle="Distribuição dos lançamentos por status" month={month} setMonth={setMonth} year={year} setYear={setYear}/><div className="kpis four">{stats.map((s,i)=><KPI key={s.name} title={s.name} value={money(s.value)} sub={`${s.count} lançamentos`} tone={['orange','green','blue','gray'][i]}/>)}</div><div className="twoCols"><Card title="Distribuição por status"><ResponsiveContainer width="100%" height={320}><RPieChart><Pie data={stats.filter(x=>x.count)} dataKey="value" nameKey="name" outerRadius={110} label>{stats.map((_,i)=><Cell key={i} fill={COLORS[i]}/>)}</Pie><Tooltip formatter={money}/><Legend/></RPieChart></ResponsiveContainer></Card><Card title="Indicadores do período"><div className="indicatorList"><div><span>Taxa de realização</span><b>{rate.toFixed(1)}%</b></div><div className="progress big"><span style={{width:`${rate}%`}}/></div><div><span>Total realizado</span><b>{money(realized)}</b></div><div><span>Total pendente</span><b>{money(stats[0].value)}</b></div><div><span>Total de lançamentos</span><b>{period.length}</b></div></div></Card></div></>}
function RecebimentoPage({db,setDb,month,setMonth,year,setYear,search,setSearch}){const rows=db.transactions.filter(l=>typeNorm(l.tipo)==='entrada'&&refMonth(l)===month&&refYear(l)===year&&(!search||`${l.descricao} ${l.natureza_nome}`.toLowerCase().includes(search.toLowerCase())));const pending=rows.filter(l=>statusNorm(l.status)==='pendente').reduce((s,l)=>s+num(l.valor),0),received=rows.filter(l=>statusNorm(l.status)==='recebido').reduce((s,l)=>s+num(l.valor),0);const receive=id=>setDb(d=>({...d,transactions:d.transactions.map(l=>String(l.id)===String(id)?{...l,status:'recebido'}:l)}));return <><Header title="Recebimento" subtitle="Controle e confirmação das contas a receber" month={month} setMonth={setMonth} year={year} setYear={setYear}/><div className="kpis"><KPI title="A Receber" value={money(pending)} tone="orange"/><KPI title="Recebido" value={money(received)}/><KPI title="Total Previsto" value={money(pending+received)} tone="blue"/></div><div className="filters"><div className="search"><Search/><input placeholder="Buscar recebimento..." value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="tableWrap"><table><thead><tr><th>Data</th><th>Vencimento</th><th>Descrição</th><th>Natureza</th><th>Valor</th><th>Status</th><th>Ação</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{dateBR(r.data)}</td><td>{dateBR(r.data_vencimento)}</td><td><b>{r.descricao}</b></td><td>{r.natureza_nome}</td><td>{money(r.valor)}</td><td><StatusBadge status={r.status}/></td><td>{statusNorm(r.status)==='pendente'&&<button className="smallPrimary" onClick={()=>receive(r.id)}><CheckCircle2/>Receber</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div></>}
function analysisData(rows,allowed=null){const filtered=rows.filter(l=>typeNorm(l.tipo)==='saida'&&isSettled(l)&&(!allowed||allowed.includes(norm(l.natureza_nome))));const by=Object.entries(filtered.reduce((a,l)=>{const k=l.natureza_nome||'Outros';a[k]=(a[k]||0)+num(l.valor);return a},{})).map(([name,value])=>({name,value})).sort((a,b)=>b.value-a.value);return{filtered,by,total:by.reduce((s,x)=>s+x.value,0)}}
function CustoDespesaPage({month,setMonth,year,setYear,realizedPeriod,income}){const d=analysisData(realizedPeriod);return <AnalysisLayout title="Análise de Custo e Despesa" subtitle="Todas as despesas realizadas por natureza" month={month} setMonth={setMonth} year={year} setYear={setYear} data={d} income={income}/>}
function CustosPage({year,setYear,realizedAnnual}){const d=analysisData(realizedAnnual,COST_NATURES);const income=realizedAnnual.filter(l=>typeNorm(l.tipo)==='entrada').reduce((s,l)=>s+num(l.valor),0);const monthly=MONTHS.map((_,i)=>{const r=realizedAnnual.filter(l=>refMonth(l)===i);return{mes:SHORT_MONTHS[i],Receitas:r.filter(l=>typeNorm(l.tipo)==='entrada').reduce((s,l)=>s+num(l.valor),0),Custos:r.filter(l=>typeNorm(l.tipo)==='saida'&&COST_NATURES.includes(norm(l.natureza_nome))).reduce((s,l)=>s+num(l.valor),0)}});return <><Header title="Análise de Custos" subtitle="Custos diretamente ligados à operação" month={0} setMonth={()=>{}} year={year} setYear={setYear} yearOnly/><div className="kpis"><KPI title="Total de Custos" value={money(d.total)} tone="red"/><KPI title="Total Receitas" value={money(income)}/><KPI title="Margem Bruta" value={pct(income-d.total,income)} tone="blue"/></div><Card title={`Receitas x Custos — ${year}`}><ResponsiveContainer width="100%" height={340}><LineChart data={monthly}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="mes"/><YAxis tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><Tooltip formatter={money}/><Legend/><Line dataKey="Receitas" stroke="#15a777" strokeWidth={3}/><Line dataKey="Custos" stroke="#ef4444" strokeWidth={3}/></LineChart></ResponsiveContainer></Card><NatureTable title="Custos por Natureza" rows={d.by} total={d.total}/></>}
function DespesasPage({month,setMonth,year,setYear,realizedPeriod}){const d=analysisData(realizedPeriod,EXPENSE_NATURES);const sumList=list=>d.filtered.filter(l=>list.includes(norm(l.natureza_nome))).reduce((s,l)=>s+num(l.valor),0);return <><Header title="Análise de Despesas" subtitle="Despesas operacionais, administrativas e com pessoal" month={month} setMonth={setMonth} year={year} setYear={setYear}/><div className="kpis four"><KPI title="Total Despesas" value={money(d.total)} tone="red"/><KPI title="Despesas c/ Pessoal" value={money(sumList(PERSONNEL))} tone="orange"/><KPI title="Despesas Adm." value={money(sumList(ADMIN))} tone="blue"/><KPI title="Impostos" value={money(sumList(TAXES))} tone="gray"/></div><div className="twoCols"><Card title="Top 10 despesas"><ResponsiveContainer width="100%" height={360}><BarChart layout="vertical" data={d.by.slice(0,10)}><CartesianGrid strokeDasharray="3 3"/><XAxis type="number" tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><YAxis dataKey="name" type="category" width={145} tickFormatter={v=>v.length>20?v.slice(0,20)+'…':v}/><Tooltip formatter={money}/><Bar dataKey="value" fill="#ef4444"/></BarChart></ResponsiveContainer></Card><NatureTable title="Detalhamento" rows={d.by} total={d.total}/></div></>}
function MargemPage({year,setYear,annual}){const data=annualMonthly(annual),tr=data.reduce((s,x)=>s+x.Receitas,0),td=data.reduce((s,x)=>s+x.Despesas,0),lucro=tr-td,margem=tr?lucro/tr*100:0;const best=[...data].sort((a,b)=>b.lucro-a.lucro)[0],worst=[...data].filter(x=>x.Receitas>0).sort((a,b)=>a.lucro-b.lucro)[0];return <><Header title="Margem de Lucro" subtitle="Rentabilidade mensal e anual" month={0} setMonth={()=>{}} year={year} setYear={setYear} yearOnly/><div className="kpis four"><KPI title="Receita Total" value={money(tr)}/><KPI title="Despesa Total" value={money(td)} tone="red"/><KPI title="Lucro Líquido" value={money(lucro)} tone={lucro>=0?'blue':'orange'}/><KPI title="Margem Média" value={`${margem.toFixed(1)}%`} tone="gray"/></div><Card title={`Rentabilidade — ${year}`}><ResponsiveContainer width="100%" height={370}><ComposedChart data={data}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="mes"/><YAxis yAxisId="money" tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><YAxis yAxisId="pct" orientation="right" tickFormatter={v=>`${v}%`}/><Tooltip formatter={(v,n)=>n==='margem'?`${num(v).toFixed(1)}%`:money(v)}/><Legend/><Bar yAxisId="money" dataKey="Receitas" fill="#15a777"/><Bar yAxisId="money" dataKey="Despesas" fill="#ef4444"/><Line yAxisId="pct" dataKey="margem" stroke="#3b82f6" strokeWidth={3}/></ComposedChart></ResponsiveContainer></Card><div className="twoCols"><MonthlyTable data={data} margin/><Card title="Indicadores de Performance"><div className="indicatorList"><div><span>Melhor mês</span><b>{best?.mes} • {money(best?.lucro)}</b></div><div><span>Menor performance</span><b>{worst?.mes||'—'} • {money(worst?.lucro||0)}</b></div><div><span>Receita média/mês</span><b>{money(tr/12)}</b></div><div><span>Despesa média/mês</span><b>{money(td/12)}</b></div><div><span>Meses lucrativos</span><b>{data.filter(x=>x.lucro>0).length} de 12</b></div></div></Card></div></>}
function ProjecoesPage({db,setDb,month,setMonth,year,setYear,setProjectionModal,setDeleteState}){const settings=db.projectionSettings||{lookback:3,safety:10,openingBalance:0};const updateSettings=patch=>setDb(d=>({...d,projectionSettings:{...d.projectionSettings,...patch}}));const generate=()=>{const look=Math.max(1,num(settings.lookback));const generated=[];for(let target=month+1;target<12;target++){db.natures.filter(n=>n.ativo!==false).forEach(n=>{const hist=[];for(let i=Math.max(0,month-look+1);i<=month;i++){const value=db.transactions.filter(l=>refYear(l)===year&&refMonth(l)===i&&isSettled(l)&&(String(l.natureza_id)===String(n.id)||norm(l.natureza_nome)===norm(n.nome))).reduce((s,l)=>s+num(l.valor),0);hist.push(value)}const avg=hist.reduce((a,b)=>a+b,0)/Math.max(1,hist.length);if(avg>0)generated.push({id:uid(),natureza_id:n.id,natureza_nome:n.nome,tipo:n.tipo==='receita'?'entrada':'saida',mes:target,ano:year,valor:n.tipo==='receita'?avg:avg*(1+num(settings.safety)/100),source:'Automática',method:`Média ${look} meses`})})}setDb(d=>({...d,projections:[...d.projections.filter(x=>x.source==='Manual'||x.ano!==year),...generated]}))};const entries=db.projections.filter(x=>num(x.ano)===year&&num(x.mes)>month).sort((a,b)=>a.mes-b.mes||String(a.natureza_nome).localeCompare(String(b.natureza_nome)));const summary=MONTHS.slice(month+1).map((m,j)=>{const mi=month+1+j;const rows=entries.filter(x=>num(x.mes)===mi);const entradas=rows.filter(x=>typeNorm(x.tipo)==='entrada').reduce((s,x)=>s+num(x.valor),0);const saidas=rows.filter(x=>typeNorm(x.tipo)==='saida').reduce((s,x)=>s+num(x.valor),0);return{mes:m,Entradas:entradas,Saídas:saidas,saldo:entradas-saidas}});let acc=num(settings.openingBalance);summary.forEach(x=>{acc+=x.saldo;x.acumulado=acc});const tin=summary.reduce((s,x)=>s+x.Entradas,0),tout=summary.reduce((s,x)=>s+x.Saídas,0);return <><Header title="Planejamento e Projeções" subtitle="Projeção separada dos relatórios oficiais do Base44" month={month} setMonth={setMonth} year={year} setYear={setYear} action={<button className="primary" onClick={()=>setProjectionModal({natureza_id:db.natures[0]?.id||'',natureza_nome:db.natures[0]?.nome||'',tipo:'saida',mes:month+1,ano:year,valor:'',source:'Manual'})}><Plus/>Previsão manual</button>}/><Card title="Parâmetros da projeção"><div className="settingsGrid"><Field label="Média dos últimos meses" type="number" min="1" max="12" value={settings.lookback} onChange={e=>updateSettings({lookback:num(e.target.value)})}/><Field label="Margem de segurança nas despesas (%)" type="number" min="0" value={settings.safety} onChange={e=>updateSettings({safety:num(e.target.value)})}/><Field label="Saldo inicial da projeção" type="number" step="0.01" value={settings.openingBalance} onChange={e=>updateSettings({openingBalance:num(e.target.value)})}/><button className="primary generate" onClick={generate}><RefreshCw/>Gerar/Recalcular</button></div><p className="hint">As projeções não alteram DRE, fluxo de caixa, orçamento ou demais indicadores oficiais.</p></Card><div className="kpis four"><KPI title="Entradas Projetadas" value={money(tin)}/><KPI title="Saídas Projetadas" value={money(tout)} tone="red"/><KPI title="Resultado Projetado" value={money(tin-tout)} tone={tin-tout>=0?'blue':'orange'}/><KPI title="Saldo Final Projetado" value={money(acc)} tone={acc>=0?'green':'red'}/></div><Card title="Resumo até dezembro"><ResponsiveContainer width="100%" height={330}><ComposedChart data={summary}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="mes"/><YAxis tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><Tooltip formatter={money}/><Legend/><Bar dataKey="Entradas" fill="#15a777"/><Bar dataKey="Saídas" fill="#ef4444"/><Line dataKey="acumulado" stroke="#3b82f6" strokeWidth={3}/></ComposedChart></ResponsiveContainer></Card><div className="tableWrap"><table><thead><tr><th>Mês</th><th>Natureza</th><th>Tipo</th><th>Valor</th><th>Origem</th><th>Método</th><th>Ações</th></tr></thead><tbody>{entries.map(x=><tr key={x.id}><td>{MONTHS[x.mes]}</td><td><b>{x.natureza_nome}</b></td><td><Badge tone={typeNorm(x.tipo)==='entrada'?'ok':'bad'}>{displayType(x.tipo)}</Badge></td><td>{money(x.valor)}</td><td><Badge tone={x.source==='Manual'?'blue':'gray'}>{x.source}</Badge></td><td>{x.method||'Informado manualmente'}</td><td className="actions"><button onClick={()=>setProjectionModal(x)}><Pencil/></button><button className="danger" onClick={()=>setDeleteState({kind:'projection',id:x.id})}><Trash2/></button></td></tr>)}</tbody></table>{!entries.length&&<Empty text="Gere a projeção ou adicione uma previsão manual."/>}</div></>}
function BoletosPage({db,setBoletoModal,setDeleteState}){const[query,setQuery]=useState(''),[status,setStatus]=useState('todos');const today=new Date();const shownStatus=b=>{if(statusNorm(b.status)==='pago')return'pago';const due=new Date(`${b.data_vencimento}T12:00:00`);return due<today?'vencido':'pendente'};const rows=db.boletos.filter(b=>(!query||`${b.fornecedor} ${b.descricao}`.toLowerCase().includes(query.toLowerCase()))&&(status==='todos'||shownStatus(b)===status));return <><Header title="Boletos" subtitle="Documentos de cobrança e lançamentos vinculados" month={0} setMonth={()=>{}} year={2026} setYear={()=>{}} yearOnly action={<button className="primary" onClick={()=>setBoletoModal({fornecedor:'',natureza_id:db.natures[0]?.id||'',descricao:'',competencia_mes:new Date().getMonth()+1,competencia_ano:2026,data_vencimento:'',valor:'',status:'pendente',codigo_barras:'',arquivo_url:''})}><Plus/>Novo Boleto</button>}/><div className="filters"><div className="search"><Search/><input placeholder="Fornecedor ou descrição..." value={query} onChange={e=>setQuery(e.target.value)}/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="todos">Todos</option><option value="pendente">Pendente</option><option value="pago">Pago</option><option value="vencido">Vencido</option></select></div><div className="tableWrap"><table><thead><tr><th>Fornecedor</th><th>Descrição</th><th>Competência</th><th>Vencimento</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>{rows.map(b=><tr key={b.id}><td><b>{b.fornecedor}</b></td><td>{b.descricao}</td><td>{String(b.competencia_mes).padStart(2,'0')}/{b.competencia_ano}</td><td>{dateBR(b.data_vencimento)}</td><td>{money(b.valor)}</td><td><Badge tone={shownStatus(b)==='pago'?'ok':shownStatus(b)==='vencido'?'bad':'warn'}>{shownStatus(b)}</Badge></td><td className="actions"><button onClick={()=>setBoletoModal(b)}><Pencil/></button>{b.arquivo_url&&<a className="iconLink" href={b.arquivo_url} target="_blank"><Eye/></a>}<button className="danger" onClick={()=>setDeleteState({kind:'boleto',id:b.id})}><Trash2/></button></td></tr>)}</tbody></table>{!rows.length&&<Empty text="Nenhum boleto cadastrado."/>}</div></>}
function ExportPage({db,month,year,period,annual,realizedPeriod,realizedAnnual}){const save=(name,sheets)=>{const wb=XLSX.utils.book_new();Object.entries(sheets).forEach(([sheet,rows])=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),sheet.slice(0,31)));XLSX.writeFile(wb,name)};const txRows=db.transactions.map(l=>({Data:l.data,Vencimento:l.data_vencimento,Descrição:l.descricao,Natureza:l.natureza_nome,Tipo:displayType(l.tipo),Valor:l.valor,Status:l.status,'Mês Referência':l.mes_referencia,'Ano Referência':l.ano_referencia,Observação:l.observacao}));const exports=[['Lançamentos',()=>save('GIFT_Lancamentos.xlsx',{Lançamentos:txRows})],['Naturezas',()=>save('GIFT_Naturezas.xlsx',{Naturezas:db.natures})],['Orçamentos',()=>save('GIFT_Orcamentos.xlsx',{Orçamentos:db.budgets})],['DRE',()=>save(`GIFT_DRE_${month+1}_${year}.xlsx`,{DRE:[{Indicador:'Receita Bruta',Valor:realizedPeriod.filter(l=>typeNorm(l.tipo)==='entrada').reduce((s,l)=>s+num(l.valor),0)},{Indicador:'Despesas',Valor:realizedPeriod.filter(l=>typeNorm(l.tipo)==='saida').reduce((s,l)=>s+num(l.valor),0)}]})],['Fluxo de Caixa',()=>save(`GIFT_Fluxo_${year}.xlsx`,{'Fluxo de Caixa':annualMonthly(annual)})],['Valores Mensais',()=>save(`GIFT_Valores_Mensais_${year}.xlsx`,{'Valores Mensais':annualMonthly(annual)})],['Ciclo Financeiro',()=>save(`GIFT_Ciclo_${month+1}_${year}.xlsx`,{'Ciclo Financeiro':period})],['Recebimentos',()=>save(`GIFT_Recebimentos_${month+1}_${year}.xlsx`,{Recebimentos:period.filter(l=>typeNorm(l.tipo)==='entrada')})],['Análise Custo/Despesa',()=>save(`GIFT_Custo_Despesa_${month+1}_${year}.xlsx`,{Análise:analysisData(realizedPeriod).by})],['Análise de Custos',()=>save(`GIFT_Custos_${year}.xlsx`,{Custos:analysisData(realizedAnnual,COST_NATURES).by})],['Análise de Despesas',()=>save(`GIFT_Despesas_${month+1}_${year}.xlsx`,{Despesas:analysisData(realizedPeriod,EXPENSE_NATURES).by})],['Margem de Lucro',()=>save(`GIFT_Margem_${year}.xlsx`,{Margem:annualMonthly(annual)})]];return <><Header title="Exportar Excel" subtitle="Arquivos usando exatamente as mesmas regras das telas" month={month} setMonth={()=>{}} year={year} setYear={()=>{}}/><div className="exportHero"><FileSpreadsheet/><div><h3>Exportar sistema completo</h3><p>Lançamentos, naturezas, orçamentos, boletos e projeções.</p></div><button className="primary" onClick={()=>save(`GIFT_Financeiro_Completo_${year}.xlsx`,{Lançamentos:txRows,Naturezas:db.natures,Orçamentos:db.budgets,Boletos:db.boletos,Projeções:db.projections})}><Download/>Exportar Completo</button></div><div className="exportGrid">{exports.map(([name,fn])=><div className="exportCard" key={name}><FileSpreadsheet/><div><b>{name}</b><span>Exportação compatível com a tela</span></div><button onClick={fn}><Download/>Exportar</button></div>)}</div><div className="notice"><CheckCircle2/><div><b>Divergências do Base44 corrigidas</b><p>Análise de Custos e Análise de Despesas usam no Excel as mesmas listas e regras exibidas nas telas.</p></div></div></>}

function AnalysisLayout({title,subtitle,month,setMonth,year,setYear,data,income}){return <><Header title={title} subtitle={subtitle} month={month} setMonth={setMonth} year={year} setYear={setYear}/><div className="kpis"><KPI title="Total Despesas" value={money(data.total)} tone="red"/><KPI title="Total Receitas" value={money(income)}/><KPI title="Despesas / Receita" value={pct(data.total,income)} tone="orange"/></div><div className="twoCols"><Card title="Top 10 por natureza"><ResponsiveContainer width="100%" height={360}><BarChart layout="vertical" data={data.by.slice(0,10)}><CartesianGrid strokeDasharray="3 3"/><XAxis type="number" tickFormatter={v=>`R$ ${Math.round(v/1000)}k`}/><YAxis dataKey="name" type="category" width={150}/><Tooltip formatter={money}/><Bar dataKey="value" fill="#ef4444"/></BarChart></ResponsiveContainer></Card><Card title="Distribuição percentual"><ResponsiveContainer width="100%" height={360}><RPieChart><Pie data={data.by.slice(0,10)} dataKey="value" nameKey="name" outerRadius={110} label>{data.by.slice(0,10).map((_,i)=><Cell key={i} fill={COLORS[i%COLORS.length]}/>)}</Pie><Tooltip formatter={money}/></RPieChart></ResponsiveContainer></Card></div><NatureTable title="Detalhamento por Natureza" rows={data.by} total={data.total}/></>}
function NatureTable({title,rows,total}){return <Card title={title}><div className="miniTable"><div className="miniHead"><span>Natureza</span><span>Valor</span><span>%</span></div>{rows.map(r=><div key={r.name}><span>{r.name}</span><b>{money(r.value)}</b><em>{total?(r.value/total*100).toFixed(1):0}%</em></div>)}<div className="miniTotal"><span>TOTAL</span><b>{money(total)}</b><em>100%</em></div></div></Card>}
function MonthlyTable({data,margin=false}){return <Card title="Detalhamento Mensal"><div className="tableWrap inner"><table><thead><tr><th>Mês</th><th>Receitas</th><th>Despesas</th><th>Saldo/Lucro</th>{margin&&<th>Margem</th>}<th>Acumulado</th></tr></thead><tbody>{data.map(x=><tr key={x.mes}><td><b>{x.mes}</b></td><td className="positive">{money(x.Receitas)}</td><td className="negative">{money(x.Despesas)}</td><td>{money(x.saldo)}</td>{margin&&<td>{x.margem.toFixed(1)}%</td>}<td>{money(x.acumulado)}</td></tr>)}</tbody></table></div></Card>}

function TxModal({initial,natures,onSave,onClose}){const[f,setF]=useState({...initial});return <Modal title={f.id?'Editar lançamento':'Novo lançamento'} onClose={onClose} size="large"><form onSubmit={e=>{e.preventDefault();onSave(f)}}><div className="formGrid"><Field label="Descrição" required value={f.descricao||''} onChange={e=>setF({...f,descricao:e.target.value})}/><SelectField label="Natureza" required value={f.natureza_id||''} onChange={e=>setF({...f,natureza_id:e.target.value})}>{natures.map(n=><option key={n.id} value={n.id}>{n.nome}</option>)}</SelectField><SelectField label="Tipo" value={typeNorm(f.tipo)} onChange={e=>setF({...f,tipo:e.target.value})}><option value="entrada">Entrada</option><option value="saida">Saída</option></SelectField><Field label="Valor" type="number" min="0" step="0.01" required value={f.valor||''} onChange={e=>setF({...f,valor:e.target.value})}/><SelectField label="Status" value={statusNorm(f.status)} onChange={e=>setF({...f,status:e.target.value})}><option value="pendente">Pendente</option><option value="pago">Pago</option><option value="recebido">Recebido</option><option value="cancelado">Cancelado</option></SelectField><Field label="Data" type="date" required value={f.data||''} onChange={e=>setF({...f,data:e.target.value})}/><Field label="Vencimento" type="date" value={f.data_vencimento||''} onChange={e=>setF({...f,data_vencimento:e.target.value})}/><TextArea label="Observação" value={f.observacao||''} onChange={e=>setF({...f,observacao:e.target.value})}/></div><div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary"><Save/>Salvar</button></div></form></Modal>}
function NatureModal({initial,onSave,onClose}){const[f,setF]=useState({...initial});return <Modal title={f.id?'Editar natureza':'Nova natureza'} onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(f)}}><div className="formGrid one"><Field label="Nome" required value={f.nome||''} onChange={e=>setF({...f,nome:e.target.value})}/><SelectField label="Tipo" value={f.tipo||'despesa'} onChange={e=>setF({...f,tipo:e.target.value})}><option value="receita">Receita</option><option value="despesa">Despesa</option><option value="transferencia">Transferência</option></SelectField></div><div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary"><Save/>Salvar</button></div></form></Modal>}
function BudgetModal({initial,onSave,onClose}){const[v,setV]=useState(initial.value||'');return <Modal title="Definir orçamento" onClose={onClose}><form onSubmit={e=>{e.preventDefault();onSave(v)}}><Field label="Valor previsto" type="number" min="0" step="0.01" value={v} onChange={e=>setV(e.target.value)}/><div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary"><Save/>Salvar</button></div></form></Modal>}
function BoletoModal({initial,natures,onSave,onClose}){
 const[f,setF]=useState({...initial});const[scanning,setScanning]=useState(false);const[scanProgress,setScanProgress]=useState(0);const[scanError,setScanError]=useState('');const[preview,setPreview]=useState(initial.arquivo_url||'');
 const scanFile=async file=>{if(!file)return;setScanError('');setScanning(true);setScanProgress(0);try{const r=await readBoletoImage(file,setScanProgress);setPreview(r.url);setF(x=>({...x,codigo_barras:r.barcode||x.codigo_barras,valor:r.value||x.valor,data_vencimento:r.due||x.data_vencimento,arquivo_url:r.url}));if(!r.barcode)setScanError('Não consegui identificar a linha digitável. Você pode preencher manualmente e salvar a imagem normalmente.')}catch(e){console.error(e);setScanError('Não foi possível ler esta imagem. Tente uma foto mais nítida, reta e sem reflexos.')}finally{setScanning(false)}};
 return <Modal title={f.id?'Editar boleto':'Novo boleto'} onClose={onClose} size="large"><form onSubmit={e=>{e.preventDefault();onSave(f)}}>
 <div className="scanPanel"><div className="scanInfo"><div className="scanIcon"><ScanLine/></div><div><b>Ler boleto por imagem</b><p>Envie uma foto nítida do código de barras ou da linha digitável. O sistema tenta preencher código, valor e vencimento.</p></div></div><label className={`primary scanButton ${scanning?'disabled':''}`}><ImagePlus/>{scanning?`Lendo ${scanProgress}%`:'Selecionar imagem'}<input type="file" accept="image/png,image/jpeg,image/webp" capture="environment" disabled={scanning} onChange={e=>scanFile(e.target.files?.[0])}/></label></div>
 {preview&&<div className="scanPreview"><img src={preview} alt="Prévia do boleto"/><span>Imagem anexada ao cadastro</span></div>}
 {scanning&&<div className="scanProgress"><span style={{width:`${Math.max(8,scanProgress)}%`}}/></div>}
 {scanError&&<div className="scanWarning"><AlertTriangle/>{scanError}</div>}
 <div className="formGrid"><Field label="Fornecedor" required value={f.fornecedor||''} onChange={e=>setF({...f,fornecedor:e.target.value})}/><SelectField label="Natureza" value={f.natureza_id||''} onChange={e=>setF({...f,natureza_id:e.target.value})}>{natures.map(n=><option key={n.id} value={n.id}>{n.nome}</option>)}</SelectField><Field label="Descrição" value={f.descricao||''} onChange={e=>setF({...f,descricao:e.target.value})}/><Field label="Valor" type="number" min="0" step="0.01" required value={f.valor||''} onChange={e=>setF({...f,valor:e.target.value})}/><Field label="Competência mês" type="number" min="1" max="12" required value={f.competencia_mes||''} onChange={e=>setF({...f,competencia_mes:e.target.value})}/><Field label="Competência ano" type="number" required value={f.competencia_ano||''} onChange={e=>setF({...f,competencia_ano:e.target.value})}/><Field label="Vencimento" type="date" required value={f.data_vencimento||''} onChange={e=>setF({...f,data_vencimento:e.target.value})}/><SelectField label="Status" value={f.status||'pendente'} onChange={e=>setF({...f,status:e.target.value})}><option value="pendente">Pendente</option><option value="pago">Pago</option></SelectField><Field label="Código de barras / linha digitável" value={f.codigo_barras||''} onChange={e=>setF({...f,codigo_barras:e.target.value})}/><Field label="URL do arquivo" value={f.arquivo_url||''} onChange={e=>setF({...f,arquivo_url:e.target.value})}/></div><div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={scanning}><Save/>Salvar boleto</button></div></form></Modal>}

function ProjectionModal({initial,natures,year,onSave,onClose}){const[f,setF]=useState({...initial});return <Modal title={f.id?'Editar previsão':'Nova previsão manual'} onClose={onClose}><form onSubmit={e=>{e.preventDefault();const n=natures.find(x=>String(x.id)===String(f.natureza_id));onSave({...f,natureza_nome:n?.nome||f.natureza_nome,tipo:n?.tipo==='receita'?'entrada':'saida'})}}><div className="formGrid one"><SelectField label="Mês" value={f.mes} onChange={e=>setF({...f,mes:+e.target.value})}>{MONTHS.map((m,i)=><option key={m} value={i}>{m}</option>)}</SelectField><Field label="Ano" type="number" value={f.ano||year} onChange={e=>setF({...f,ano:+e.target.value})}/><SelectField label="Natureza" value={f.natureza_id||''} onChange={e=>setF({...f,natureza_id:e.target.value})}>{natures.map(n=><option key={n.id} value={n.id}>{n.nome}</option>)}</SelectField><Field label="Valor previsto" type="number" min="0" step="0.01" required value={f.valor||''} onChange={e=>setF({...f,valor:e.target.value})}/></div><div className="modalActions"><button type="button" className="secondary" onClick={onClose}>Cancelar</button><button className="primary"><Save/>Salvar previsão</button></div></form></Modal>}

createRoot(document.getElementById('root')).render(<App/>);
